package org.stackdocs.app;
import android.database.*;import android.database.sqlite.*;import org.json.*;import java.io.*;import java.util.*;import java.security.*;import java.nio.charset.StandardCharsets;
public final class ReadOnlyMigration{
 static final File ROOT=new File("/data/user/0/org.stackdocs.app/files");
 public static void main(String[]args){try(SQLiteDatabase db=SQLiteDatabase.openDatabase("/data/user/0/org.stackdocs.app/databases/library.db",null,SQLiteDatabase.OPEN_READONLY)){
  JSONObject out=new JSONObject(),catalog=new JSONObject();for(String table:new String[]{"documents","pages","stacks","document_stacks","details"})out.put(table,count(db,"SELECT count(*) FROM "+table));
  try(Cursor c=db.rawQuery("SELECT id,name,color,visible FROM stacks ORDER BY id",null)){while(c.moveToNext())catalog.put(hash(c.getString(0)),hash(c.getString(0)+"\u0000"+c.getString(1)+"\u0000"+c.getString(2)+"\u0000"+c.getString(3)));}out.put("catalog_rows",catalog);
  MessageDigest local=MessageDigest.getInstance("SHA-256");for(String name:new String[]{"scan_draft","consolidation_recovery"})files(ROOT,new File(ROOT,name),local);out.put("draft_recovery_sha256",hex(local.digest()));
  JSONObject states=new JSONObject();try(Cursor c=db.rawQuery("SELECT ocr_state,count(*) FROM pages GROUP BY ocr_state",null)){while(c.moveToNext())states.put(c.getString(0),c.getInt(1));}out.put("ocr",states);
  if(args.length>0&&args[0].equals("verify")){
   ByteArrayOutputStream input=new ByteArrayOutputStream();byte[] buffer=new byte[65536];int n;while((n=System.in.read(buffer))!=-1){input.write(buffer,0,n);require(input.size()<=32*1024*1024,"manifest limit");}JSONObject source=new JSONObject(input.toString("UTF-8"));Map<String,String> docs=new HashMap<>(),stacks=new HashMap<>();
   JSONArray details=source.getJSONArray("details");for(int i=0;i<details.length();i++){JSONObject row=details.getJSONObject(i);if(row.getString("label").equals("Original scan date"))try(Cursor c=db.rawQuery("SELECT document_id FROM details WHERE field_id=?",new String[]{row.getString("field_id")})){require(c.moveToFirst(),"source document mapping");docs.put(row.getString("document_id"),c.getString(0));require(!c.moveToNext(),"source identity uniqueness");}}
   JSONArray sourceStacks=source.getJSONArray("stacks");for(int i=0;i<sourceStacks.length();i++){JSONObject row=sourceStacks.getJSONObject(i);try(Cursor c=db.rawQuery("SELECT id FROM stacks WHERE name=? COLLATE NOCASE",new String[]{row.getString("name")})){require(c.moveToFirst(),"source category mapping");stacks.put(row.getString("id"),c.getString(0));require(!c.moveToNext(),"category uniqueness");}}
   JSONArray documents=source.getJSONArray("documents");require(docs.size()==documents.length()&&count(db,"SELECT count(*) FROM documents")==documents.length(),"document set exact");
   for(int i=0;i<documents.length();i++){JSONObject row=documents.getJSONObject(i);compare(db,"documents","id=?",new String[]{docs.get(row.getString("id"))},row,"title,mime,added_at,page_count,title_user_edited,initial_page_count,source_scan_id,title_origin,filing_origin,title_decision,filing_decision,notes,notes_revision");}
   JSONArray pages=source.getJSONArray("pages");for(int i=0;i<pages.length();i++){JSONObject row=pages.getJSONObject(i);compare(db,"pages","document_id=? AND position=?",new String[]{docs.get(row.getString("document_id")),row.getString("position")},row,"position,source_page,rotation,crop,enhancement,source_file,flatten,content_revision");}require(count(db,"SELECT count(*) FROM pages")==pages.length(),"page set exact");
   for(int i=0;i<details.length();i++){JSONObject row=details.getJSONObject(i);compare(db,"details","document_id=? AND field_id=?",new String[]{docs.get(row.getString("document_id")),row.getString("field_id")},row,"field_id,kind,label,value,qualifier,origin,state,evidence,revision");}
   Map<String,Set<String>> expected=new HashMap<>();for(String id:docs.values())expected.put(id,new HashSet<>());JSONArray memberships=source.getJSONArray("memberships");for(int i=0;i<memberships.length();i++){JSONObject row=memberships.getJSONObject(i);expected.get(docs.get(row.getString("document_id"))).add(stacks.get(row.getString("stack_id")));}
   for(String doc:expected.keySet()){Set<String> actual=new HashSet<>();try(Cursor c=db.rawQuery("SELECT stack_id FROM document_stacks WHERE document_id=?",new String[]{doc})){while(c.moveToNext())actual.add(c.getString(0));}require(actual.equals(expected.get(doc)),"filing exact");}
   JSONArray originals=source.getJSONArray("files");long bytes=0;for(int i=0;i<originals.length();i++){JSONObject entry=originals.getJSONObject(i);String[] path=entry.getString("path").split("/");File file=new File(ROOT,"documents/"+docs.get(path[1])+"/"+path[2]);require(file.length()==entry.getLong("length"),"original length");MessageDigest digest=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(file)){while((n=in.read(buffer))!=-1)digest.update(buffer,0,n);}require(hex(digest.digest()).equals(entry.getString("sha256")),"original digest");bytes+=file.length();}
   out.put("source_documents_verified",documents.length()).put("source_pages_verified",pages.length()).put("source_detail_rows_verified",details.length()).put("source_memberships_verified",memberships.length()).put("source_originals_verified",originals.length()).put("source_original_bytes_verified",bytes).put("source_metadata_and_originals_match",true);
  }
  System.out.println(out.toString());
 }catch(Throwable error){System.out.println("{\"verification_unavailable\":true,\"error_class\":\""+error.getClass().getSimpleName()+"\"}");System.exit(2);}}
 static void compare(SQLiteDatabase db,String table,String where,String[]args,JSONObject expected,String columns)throws Exception{String[] fields=columns.split(",");try(Cursor row=db.query(table,fields,where,args,null,null,null)){require(row.moveToFirst(),"source row present");for(int i=0;i<fields.length;i++){Object value=expected.get(fields[i]);if(value==JSONObject.NULL)require(row.isNull(i),"source null");else if(fields[i].equals("evidence"))require(canonical(new JSONObject(value.toString())).equals(canonical(new JSONObject(row.getString(i)))),"source provenance");else require(value.toString().equals(row.getString(i)),"source field exact");}require(!row.moveToNext(),"source row unique");}}
 static String canonical(Object value)throws Exception{if(value instanceof Number)return new java.math.BigDecimal(value.toString()).stripTrailingZeros().toPlainString();if(value instanceof JSONObject){JSONObject json=(JSONObject)value;TreeSet<String> keys=new TreeSet<>();json.keys().forEachRemaining(keys::add);StringBuilder s=new StringBuilder("{");for(String k:keys)s.append(k.length()).append(':').append(k).append(canonical(json.get(k)));return s+"}";}if(value instanceof JSONArray){StringBuilder s=new StringBuilder("[");JSONArray a=(JSONArray)value;for(int i=0;i<a.length();i++)s.append(canonical(a.get(i)));return s+"]";}return value==JSONObject.NULL?"null":value.toString().length()+":"+value;}
 static void files(File base,File file,MessageDigest hash)throws Exception{if(file.isDirectory()){File[] children=file.listFiles();require(children!=null,"local files readable");Arrays.sort(children,Comparator.comparing(File::getName));for(File child:children)files(base,child,hash);}else if(file.isFile()){String path=base.toURI().relativize(file.toURI()).getPath();hash.update((path.length()+":"+path+":"+file.length()+":").getBytes(StandardCharsets.UTF_8));try(InputStream in=new FileInputStream(file)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)hash.update(b,0,n);}}}
 static String hash(String s)throws Exception{return hex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}static String hex(byte[] bytes){StringBuilder b=new StringBuilder();for(byte v:bytes)b.append(String.format(Locale.ROOT,"%02x",v&255));return b.toString();}static long count(SQLiteDatabase db,String sql){try(Cursor c=db.rawQuery(sql,null)){c.moveToFirst();return c.getLong(0);}}static void require(boolean ok,String label){if(!ok)throw new IllegalStateException(label);}
}
